mapper.insert:
/* userDAO.insertUserInfo */
INSERT INTO member.user_info (user_id, user_pw, name, email, phone, birth_dt, status, reg_dt, mod_dt, use_yn)
VALUES (#{userId}, #{userPw}, #{name}, #{email}, #{phone}, #{birthDt}, 'A', NOW(), NULL, 'Y')

mapper.select:
/* userDAO.selectUserInfo */ SELECT seq, user_id, user_pw, name, email, phone, birth_dt, status, DATE_FORMAT(reg_dt, '%Y-%m-%d %H:%i:%s') as regDt, DATE_FORMAT(mod_dt, '%Y-%m-%d %H:%i:%s') as modDt, use_yn FROM member.user_info WHERE 1 = 1
AND seq = #{seq}
AND user_id = #{id}

mapper.update:
/* userDAO.updateTodo */
UPDATE member.user_todo
SET
	title = #{title},
	memo = #{memo},
	status = #{status},
	mod_dt = NOW()
WHERE seq = #{seq}
  AND user_seq = #{userSeq}
  AND use_yn = 'Y'

/* userDAO.deleteTodo */
UPDATE member.user_todo
SET
	use_yn = 'N',
	mod_dt = NOW()
WHERE seq = #{seq}
  AND user_seq = #{userSeq}
  AND use_yn = 'Y'
